{
  "items": [
    {
      "title": "Shell Youth Study 2019 (Shell Jugendstudie) – Cumulative Dataset 2002, 2006, 2010, 2015, 2019",
      "url_or_doi": "https://doi.org/10.7802/2106",
      "justification": "One of the most relevant datasets for studying youth in Germany during the 2010s. Includes survey waves from 2010, 2015, and 2019, covering young people's attitudes, values, political orientations, social behavior, education, employment expectations, and lifestyles. Particularly useful for analyzing changes in German youth attitudes throughout the decade."
    },
    {
      "title": "Shell Youth Study 2024 – Cumulative Dataset 2002–2024",
      "url_or_doi": "https://doi.org/10.7802/2797",
      "justification": "A comprehensive dataset containing six survey waves, including those conducted in 2010, 2015, and 2019. Examines the attitudes, values, habits, and social behavior of adolescents and young adults in Germany. The cumulative structure facilitates comparisons between the 2010s and subsequent years. Available through the GESIS Data Archive with free registration."
    },
    {
      "title": "Growing Up in Germany: Everyday Worlds (AID:A II), 2014",
      "url_or_doi": "https://www.dji.de/en/about-us/projects/projekte/aida-ii-aufwachsen-in-deutschland-alltagswelten.html",
      "justification": "Conducted by the German Youth Institute (Deutsches Jugendinstitut, DJI), this study investigates the living conditions and everyday experiences of children, adolescents, and young adults in Germany. The 2014 survey covers individuals up to age 32 and examines family relationships, education, employment, social inequalities, and transitions into adulthood. Especially relevant for understanding youth experiences in Germany during the mid-2010s."
    },
    {
      "title": "Growing Up in Germany: Everyday Life's World (AID:A), 2009",
      "url_or_doi": "https://search.gesis.org/research_data/ZA5577",
      "justification": "A large-scale survey conducted by the German Youth Institute involving more than 25,000 individuals. Although its baseline survey was conducted in 2009, it provides an important reference point for research on German youth during the 2010s. Covers education, family circumstances, social relationships, migration background, employment, and living arrangements. Can be used alongside the 2014 AID:A wave to investigate changes over time."
    },
    {
      "title": "National Educational Panel Study (NEPS) – Starting Cohort 4: Grade 9",
      "url_or_doi": "https://www.neps-data.de/Data-Center/Data-and-Documentation/NEPS-Data-Portfolio",
      "justification": "A longitudinal dataset following students who were in ninth grade in Germany during the 2010/2011 school year. Tracks their educational trajectories, competencies, school-to-work transitions, vocational training, and entry into higher education or employment. Particularly valuable for investigating how German adolescents transitioned into adulthood throughout the 2010s. Scientific Use Files are available to registered researchers."
    },
    {
      "title": "National Educational Panel Study (NEPS) – Starting Cohort 3: Grade 5",
      "url_or_doi": "https://www.neps-data.de/Data-Center/Data-and-Documentation/NEPS-Data-Portfolio",
      "justification": "A longitudinal study beginning with fifth-grade students in Germany in the 2010/2011 school year. Examines educational development, academic achievement, social background, family influences, and educational inequalities. Because participants were followed throughout the 2010s, the dataset is suitable for examining adolescent development and educational transitions during this period."
    },
    {
      "title": "National Educational Panel Study (NEPS) – Starting Cohort 5: First-Year Students",
      "url_or_doi": "https://www.lifbi.de/en-us/Start/Data-Services/Data-and-Documentation/SUF-Overview",
      "justification": "A longitudinal study of individuals beginning higher education in Germany in 2010. Includes information about educational backgrounds, university experiences, academic performance, social circumstances, and transitions into employment. Particularly relevant for studying young adults and higher education experiences in Germany during the 2010s."
    },
    {
      "title": "Children of Immigrants Longitudinal Survey in Four European Countries and NEPS – Harmonized Dataset (CILS4NEPS)",
      "url_or_doi": "https://www.cils4.eu/index.php?Itemid=241&catid=8&id=139%3Acils4neps-info&option=com_content&view=article",
      "justification": "Combines longitudinal survey information from CILS4EU and the German National Educational Panel Study. Focuses on adolescents attending ninth grade during the 2010/2011 school year. Particularly useful for examining migration background, educational inequalities, ethnic differences, social integration, and school-to-work transitions among young people in Germany during the 2010s."
    },
    {
      "title": "German Youth Institute (DJI) – Research Database: Growing Up in Germany (AID:A)",
      "url_or_doi": "https://www.dji.de/en/about-us/research-database.html",
      "justification": "An official research database containing information about major longitudinal studies conducted by the German Youth Institute, including the AID:A survey series beginning in 2009. Provides access to research resources concerning the everyday lives, education, family situations, and social development of German children and adolescents. Useful for identifying additional survey waves and datasets relevant to the 2010s."
    }
  ]
}
